function normalizeAgentWorkMatchText(value: string) {
  return value.toLowerCase().replace(/\s+/g, " ").trim();
}

/** Link a Voice Log message to its Agent Work task (by turn id, prompt, or result). */
function findAgentWorkTaskForMessage(message: ChatMessage, tasks: RealtimeWorkTask[]): RealtimeWorkTask | null {
  if (!tasks.length || message.role === "activity") return null;
  const turnID = message.turnID?.trim() || "";
  if (turnID) {
    const byTurn = tasks.find((task) => task.taskID === turnID || task.sourceTurnID === turnID);
    if (byTurn) return byTurn;
  }
  const text = normalizeAgentWorkMatchText(message.text || "");
  if (!text) return null;
  if (message.role === "user" && message.source === "realtimeVoice") {
    // Prefer exact prompt match, then a strong partial match for long utterances.
    const exact = tasks.find((task) => normalizeAgentWorkMatchText(task.prompt) === text);
    if (exact) return exact;
    return tasks.find((task) => {
      const prompt = normalizeAgentWorkMatchText(task.prompt);
      if (!prompt || prompt.length < 12) return false;
      return text.includes(prompt) || prompt.includes(text) || text.slice(0, 48) === prompt.slice(0, 48);
    }) ?? null;
  }
  if (message.role === "assistant" && message.source === "realtimeVoice") {
    return tasks.find((task) => {
      const result = normalizeAgentWorkMatchText(task.result || task.error || "");
      if (!result) return false;
      return result === text
        || text.startsWith(result.slice(0, 56))
        || result.startsWith(text.slice(0, 56));
    }) ?? null;
  }
  return null;
}

function activeRunsForThread(runs: Record<string, ActiveThreadRun>, threadID?: string) {
  if (!threadID) return [];
  return Object.values(runs)
    .filter((run) => sameID(run.threadID, threadID))
    .sort((left, right) => right.startedAt - left.startedAt);
}

function primaryMessageRun(runs: Record<string, ActiveThreadRun>, threadID?: string) {
  return activeRunsForThread(runs, threadID).find((run) => run.kind !== "realtimeDelegation");
}

function latestThreadRun(runs: Record<string, ActiveThreadRun>, threadID?: string) {
  return activeRunsForThread(runs, threadID)[0];
}

function realtimeRunKey(threadID: string, runID: string) {
  return `${threadID}::realtime::${runID}`;
}

function mergeActiveRunMessages(messages: ChatMessage[], run?: ActiveThreadRun) {
  const activeMessages = run?.messages ?? [];
  if (!activeMessages.length) return messages;
  const existingIDs = new Set(messages.map((message) => message.id));
  const missing = activeMessages.filter((message) => !existingIDs.has(message.id));
  return missing.length ? [...messages, ...missing] : messages;
}

function usableThreadTitle(title?: string | null) {
  const trimmed = title?.replace(/\s+/g, " ").trim();
  return trimmed && trimmed !== DEFAULT_THREAD_TITLE ? trimmed : undefined;
}

function chatTitleForPrompt(prompt: string) {
  const squashed = prompt.replace(/\s+/g, " ").trim();
  return squashed.length > 78 ? `${squashed.slice(0, 77).trimEnd()}...` : squashed || DEFAULT_THREAD_TITLE;
}

function usableOpenAssistThreadID(threadID?: string | null) {
  const trimmed = threadID?.trim();
  return trimmed && /^openassist-[0-9a-f-]{36}$/i.test(trimmed) ? trimmed : undefined;
}

