const noteCalloutDefinitions: Record<NoteCalloutKind, NoteCalloutAttrs> = {
  decision: { kind: "decision", title: "Decision", icon: "circle-gauge", color: "blue" },
  comment: { kind: "comment", title: "Comment", icon: "message", color: "purple" },
  next: { kind: "next", title: "Next steps", icon: "check", color: "green" },
  warning: { kind: "warning", title: "Warning", icon: "warning", color: "red" },
  info: { kind: "info", title: "Info", icon: "info", color: "blue" },
  success: { kind: "success", title: "Success", icon: "check", color: "green" },
  task: { kind: "task", title: "Task group", icon: "task", color: "orange" }
};

const publicNoteCalloutKinds: PublicNoteCalloutKind[] = ["decision", "comment", "next", "warning", "info", "success"];
const noteCalloutTitles: Record<NoteCalloutKind, string> = Object.fromEntries(
  Object.entries(noteCalloutDefinitions).map(([key, value]) => [key, value.title])
) as Record<NoteCalloutKind, string>;

const oaCalloutKindsPattern = "(decision|comment|next|warning|info|success|task)";
const oaCalloutOpeningPattern = new RegExp(`^:::\\s*${oaCalloutKindsPattern}(?:\\s+(.*?))?\\s*$`, "i");
const oaSectionCommentPattern = /^<!--\s*oa:section(?:\s+([^>]*?))?\s*-->\s*$/i;

function normalizeNoteTone(value: unknown, fallback: NoteToneKey = "orange"): NoteToneKey {
  const normalized = String(value ?? "").trim().toLowerCase();
  return noteToneOptions.some((tone) => tone.key === normalized) ? normalized as NoteToneKey : fallback;
}

function normalizeNoteIcon(value: unknown, fallback: NoteIconKey = "message"): NoteIconKey {
  const normalized = String(value ?? "").trim().toLowerCase();
  if (normalized === "circle-gauge") return "circle-gauge";
  return noteIconOptions.some((item) => item.key === normalized) ? normalized as NoteIconKey : fallback;
}

function normalizeNoteCalloutKind(value: unknown): NoteCalloutKind {
  const normalized = String(value ?? "").trim().toLowerCase();
  if (normalized in noteCalloutDefinitions) return normalized as NoteCalloutKind;
  return "info";
}

function noteIconLabel(icon: NoteIconKey) {
  switch (icon) {
    case "circle-gauge":
      return "◎";
    case "target":
      return "⌖";
    case "check":
      return "✓";
    case "warning":
      return "!";
    case "info":
      return "i";
    case "task":
      return "☑";
    case "code":
      return "</>";
    case "table":
      return "▦";
    case "message":
    default:
      return "◇";
  }
}

function noteSemanticIcon(iconOrKind: NoteIconKey | NoteCalloutKind, size = 15) {
  const icon = iconOrKind in noteCalloutDefinitions
    ? noteCalloutDefinitions[iconOrKind as NoteCalloutKind].icon
    : normalizeNoteIcon(iconOrKind);
  switch (icon) {
    case "circle-gauge":
      return <CircleGauge size={size} />;
    case "target":
      return <Target size={size} />;
    case "check":
      return <CheckCircle2 size={size} />;
    case "warning":
      return <TriangleAlert size={size} />;
    case "info":
      return <Info size={size} />;
    case "task":
      return <ListTodo size={size} />;
    case "code":
      return <Code2 size={size} />;
    case "table":
      return <Table2 size={size} />;
    case "message":
    default:
      return <MessageSquare size={size} />;
  }
}

function noteCalloutIcon(kind: NoteCalloutKind, icon?: NoteIconKey, size = 15) {
  return noteSemanticIcon(icon ?? noteCalloutDefinitions[kind].icon, size);
}

function parseOaAttributeText(value = "") {
  try {
    return parseAttributes(value) as Record<string, unknown>;
  } catch {
    return {};
  }
}

function parseOaContainerRest(rest: string | undefined) {
  const raw = (rest ?? "").trim();
  const attrMatch = raw.match(/\{([^}]*)\}/);
  const attrs = attrMatch ? parseOaAttributeText(attrMatch[1]) : {};
  const title = raw.replace(/\{[^}]*\}/g, "").trim();
  return { attrs, title };
}

function normalizeCalloutAttrs(input: Partial<NoteCalloutAttrs> & Record<string, unknown> = {}): NoteCalloutAttrs {
  const kind = normalizeNoteCalloutKind(input.kind);
  const defaults = noteCalloutDefinitions[kind];
  const title = String(input.title ?? "").trim() || defaults.title;
  return {
    kind,
    title,
    icon: normalizeNoteIcon(input.icon, defaults.icon),
    color: normalizeNoteTone(input.color, defaults.color)
  };
}

function parseCalloutOpeningLine(line: string): NoteCalloutAttrs | null {
  const match = line.trim().match(oaCalloutOpeningPattern);
  if (!match) return null;
  const kind = normalizeNoteCalloutKind(match[1]);
  const parsed = parseOaContainerRest(match[2]);
  return normalizeCalloutAttrs({
    kind,
    ...parsed.attrs,
    title: parsed.attrs.title ?? parsed.title
  });
}

function serializeCalloutAttrs(attrs: NoteCalloutAttrs) {
  const safeAttrs = normalizeCalloutAttrs(attrs);
  const pairs = [
    `title="${safeAttrs.title.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`,
    `icon="${safeAttrs.icon}"`,
    `color="${safeAttrs.color}"`
  ];
  return `{${pairs.join(" ")}}`;
}

function calloutMarkdown(kind: PublicNoteCalloutKind, body = "Text here", attrs: Partial<NoteCalloutAttrs> = {}) {
  const normalized = normalizeCalloutAttrs({ kind, ...attrs });
  const content = body.trim() || "Text here";
  return `::: ${normalized.kind} ${serializeCalloutAttrs(normalized)}\n\n${content}\n\n:::\n`;
}

function OpenAssistCalloutView({ node, updateAttributes }: NodeViewProps) {
  const attrs = normalizeCalloutAttrs(node.attrs);
  const [isRenaming, setIsRenaming] = useState(false);
  const [draftTitle, setDraftTitle] = useState(attrs.title);
  const [isCollapsed, setIsCollapsed] = useState(false);

  useEffect(() => {
    setDraftTitle(attrs.title);
  }, [attrs.title]);

  const commitTitle = () => {
    const nextTitle = draftTitle.replace(/\s+/g, " ").trim() || noteCalloutDefinitions[attrs.kind].title;
    if (nextTitle !== attrs.title) {
      updateAttributes({ title: nextTitle });
    }
    setIsRenaming(false);
  };

  return (
    <NodeViewWrapper
      className={`oa-callout-card oa-callout-card-${attrs.kind} ${isCollapsed ? "is-collapsed" : ""}`}
      data-oa-callout={attrs.kind}
      data-callout-title={attrs.title}
      data-callout-icon={attrs.icon}
      data-callout-color={attrs.color}
    >
      <div
        className="oa-callout-card-head"
        contentEditable={false}
        data-callout-icon-label={noteIconLabel(attrs.icon)}
      >
        <button
          type="button"
          className="oa-callout-collapse-button"
          aria-label={isCollapsed ? "Expand" : "Collapse"}
          title={isCollapsed ? "Expand" : "Collapse"}
          onMouseDown={(event) => event.preventDefault()}
          onClick={() => setIsCollapsed(!isCollapsed)}
        >
          {isCollapsed ? <ChevronRight size={14} strokeWidth={2.5} /> : <ChevronDown size={14} strokeWidth={2.5} />}
        </button>
        <span className="oa-callout-card-icon" aria-hidden="true">
          {noteCalloutIcon(attrs.kind, attrs.icon, 15)}
        </span>
        {isRenaming ? (
          <input
            className="oa-callout-title-input"
            value={draftTitle}
            autoFocus
            spellCheck
            onBlur={commitTitle}
            onChange={(event) => setDraftTitle(event.target.value)}
            onFocus={(event) => event.currentTarget.select()}
            onKeyDown={(event) => {
              if (event.key === "Enter") {
                event.preventDefault();
                commitTitle();
              }
              if (event.key === "Escape") {
                event.preventDefault();
                setDraftTitle(attrs.title);
                setIsRenaming(false);
              }
            }}
          />
        ) : (
          <button
            type="button"
            className="oa-callout-title-button"
            title="Rename block"
            onMouseDown={(event) => event.preventDefault()}
            onClick={() => setIsRenaming(true)}
          >
            {attrs.title}
          </button>
        )}
      </div>
      <div className="oa-callout-card-content">
        <NodeViewContent />
      </div>
    </NodeViewWrapper>
  );
}

function parseSectionStyleComment(line: string): NoteSectionStyle | null {
  const match = line.trim().match(oaSectionCommentPattern);
  if (!match) return null;
  const attrs = parseOaAttributeText(match[1] ?? "");
  const style: NoteSectionStyle = {};
  if (attrs.icon) style.icon = normalizeNoteIcon(attrs.icon);
  if (attrs.color) style.color = normalizeNoteTone(attrs.color);
  return style;
}

function serializeSectionStyleComment(style: NoteSectionStyle) {
  const attrs: string[] = [];
  if (style.icon) attrs.push(`icon="${style.icon}"`);
  if (style.color) attrs.push(`color="${style.color}"`);
  return `<!-- oa:section ${attrs.join(" ")} -->`;
}

function normalizeSectionStyleAttrs(input: Record<string, unknown> = {}): NoteSectionStyle {
  const style: NoteSectionStyle = {};
  if (input.icon) style.icon = normalizeNoteIcon(input.icon);
  if (input.color) style.color = normalizeNoteTone(input.color);
  return style;
}

function isSectionStyleCommentLine(line: string) {
  return oaSectionCommentPattern.test(line.trim());
}

function stripSectionStyleCommentLines(markdown: string) {
  return markdown
    .split(/\r?\n/)
    .filter((line) => !isSectionStyleCommentLine(line))
    .join("\n")
    .trim();
}

function sectionStyleKey(level: number, title: string) {
  return `${level}:${title.trim().toLowerCase().replace(/\s+/g, " ")}`;
}

function parseSectionStyleMap(markdown: string) {
  const map = new Map<string, NoteSectionStyle>();
  const lines = markdown.split(/\r?\n/);
  for (let index = 0; index < lines.length; index += 1) {
    const heading = lines[index].match(/^(#{2,3})\s+(.+?)\s*$/);
    if (!heading) continue;
    let cursor = index + 1;
    while (cursor < lines.length && lines[cursor].trim() === "") cursor += 1;
    const style = cursor < lines.length ? parseSectionStyleComment(lines[cursor]) : null;
    if (!style) continue;
    map.set(sectionStyleKey(heading[1].length, heading[2]), style);
  }
  return map;
}

const oaCalloutTokenizer: MarkdownTokenizer = {
  name: "oaCallout",
  level: "block",
  start: (src) => src.indexOf(":::"),
  tokenize(src, _tokens, lexer) {
    const openingMatch = src.match(new RegExp(`^:::\\s*${oaCalloutKindsPattern}(?:\\s+([^\\n]*))?\\n`, "i"));
    if (!openingMatch) return undefined;
    const openRaw = openingMatch[0];
    const closeMatch = src.slice(openRaw.length).match(/\n:::\s*(?:\n|$)/);
    if (!closeMatch || closeMatch.index == null) return undefined;
    const body = src.slice(openRaw.length, openRaw.length + closeMatch.index);
    const raw = src.slice(0, openRaw.length + closeMatch.index + closeMatch[0].length);
    const attrs = normalizeCalloutAttrs({
      kind: openingMatch[1],
      ...parseOaContainerRest(openingMatch[2]).attrs,
      title: parseOaContainerRest(openingMatch[2]).attrs.title ?? parseOaContainerRest(openingMatch[2]).title
    });
    return {
      type: "oaCallout",
      raw,
      attributes: attrs,
      tokens: lexer.blockTokens(body.trim())
    } as MarkdownToken;
  }
};

const OpenAssistCallout = TiptapNode.create({
  name: "oaCallout",
  group: "block",
  content: "block+",
  defining: true,
  isolating: true,
  addAttributes() {
    return {
      kind: {
        default: "info",
        parseHTML: (element) => element.getAttribute("data-oa-callout") ?? "info"
      },
      title: {
        default: "Info",
        parseHTML: (element) => element.getAttribute("data-callout-title") ?? "Info"
      },
      icon: {
        default: "info",
        parseHTML: (element) => element.getAttribute("data-callout-icon") ?? "info"
      },
      color: {
        default: "blue",
        parseHTML: (element) => element.getAttribute("data-callout-color") ?? "blue"
      }
    };
  },
  parseHTML() {
    return [{ tag: "section[data-oa-callout]" }];
  },
  renderHTML({ node, HTMLAttributes }) {
    const attrs = normalizeCalloutAttrs(node.attrs);
    return [
      "section",
      mergeAttributes(HTMLAttributes, {
        "data-oa-callout": attrs.kind,
        "data-callout-title": attrs.title,
        "data-callout-icon": attrs.icon,
        "data-callout-color": attrs.color,
        class: `oa-callout-card oa-callout-card-${attrs.kind}`
      }),
      [
        "div",
        {
          class: "oa-callout-card-head",
          contenteditable: "false",
          "data-callout-icon-label": noteIconLabel(attrs.icon)
        },
        ["span", { class: "oa-callout-card-icon", "aria-hidden": "true" }],
        ["strong", {}, attrs.title]
      ],
      ["div", { class: "oa-callout-card-content" }, 0]
    ];
  },
  addNodeView() {
    return ReactNodeViewRenderer(OpenAssistCalloutView);
  },
  markdownTokenName: "oaCallout",
  markdownTokenizer: oaCalloutTokenizer,
  parseMarkdown(token: MarkdownToken, helpers: MarkdownParseHelpers) {
    const tokenWithAttrs = token as MarkdownToken & { attributes?: Partial<NoteCalloutAttrs> };
    const attrs = normalizeCalloutAttrs(tokenWithAttrs.attributes ?? {});
    const content = helpers.parseChildren(token.tokens ?? []);
    return helpers.createNode("oaCallout", attrs, content.length ? content : [helpers.createNode("paragraph")]);
  },
  renderMarkdown(node: any, helpers: MarkdownRendererHelpers) {
    const attrs = normalizeCalloutAttrs(node.attrs ?? {});
    const content = helpers.renderChildren(node.content ?? [], "\n\n").trim() || "Text here";
    return `::: ${attrs.kind} ${serializeCalloutAttrs(attrs)}\n\n${content}\n\n:::`;
  }
});

const oaSectionStyleTokenizer: MarkdownTokenizer = {
  name: "oaSectionStyle",
  level: "block",
  start: (src) => src.indexOf("<!-- oa:section"),
  tokenize(src) {
    const match = src.match(/^<!--\s*oa:section(?:\s+([^>]*?))?\s*-->\s*(?:\n|$)/i);
    if (!match) return undefined;
    return {
      type: "oaSectionStyle",
      raw: match[0],
      attributes: normalizeSectionStyleAttrs(parseOaAttributeText(match[1] ?? ""))
    } as MarkdownToken;
  }
};

const OpenAssistSectionStyle = TiptapNode.create({
  name: "oaSectionStyle",
  group: "block",
  atom: true,
  selectable: false,
  draggable: false,
  addAttributes() {
    return {
      icon: {
        default: null,
        parseHTML: (element) => element.getAttribute("data-section-icon")
      },
      color: {
        default: null,
        parseHTML: (element) => element.getAttribute("data-section-color")
      }
    };
  },
  parseHTML() {
    return [{ tag: "div[data-oa-section-style]" }];
  },
  renderHTML({ node, HTMLAttributes }) {
    const style = normalizeSectionStyleAttrs(node.attrs);
    return [
      "div",
      mergeAttributes(HTMLAttributes, {
        "data-oa-section-style": "true",
        "data-section-icon": style.icon ?? "",
        "data-section-color": style.color ?? "",
        class: "oa-section-style-marker"
      })
    ];
  },
  markdownTokenName: "oaSectionStyle",
  markdownTokenizer: oaSectionStyleTokenizer,
  parseMarkdown(token: MarkdownToken, helpers: MarkdownParseHelpers) {
    const tokenWithAttrs = token as MarkdownToken & { attributes?: Record<string, unknown> };
    return helpers.createNode("oaSectionStyle", normalizeSectionStyleAttrs(tokenWithAttrs.attributes ?? {}));
  },
  renderMarkdown(node: any) {
    return serializeSectionStyleComment(normalizeSectionStyleAttrs(node.attrs ?? {}));
  }
});

function escapeMarkdownTableCell(value: string) {
  return value.replace(/\|/g, "\\|").replace(/\r?\n/g, "<br>").trim();
}

function predefinedSectionGridMarkdown(columns: 2 | 3, seedText = "", seedCells?: string[]) {
  const headers = columns === 2 ? ["Main", "Details"] : ["Now", "Next", "Later"];
  const seedLines = seedText
    .split(/\r?\n/)
    .map((line) => stripMarkdownLineSyntax(line).trim())
    .filter(Boolean);
  const cells = headers.map((_header, index) => {
    const seed = seedCells?.[index] ?? seedLines[index] ?? (index === 0 ? "Write here" : "Add details");
    return escapeMarkdownTableCell(seed);
  });
  return [
    `| ${headers.join(" | ")} |`,
    `| ${headers.map(() => "---").join(" | ")} |`,
    `| ${cells.join(" | ")} |`
  ].join("\n") + "\n";
}

function emptySectionGridMarkdown(columns: 2 | 3) {
  return predefinedSectionGridMarkdown(columns, "", Array.from({ length: columns }, () => ""));
}

