const LiquidGlassRuntimeContext = createContext({ enabled: false, supported: false });

function detectLiquidGlassSupport() {
  if (typeof window === "undefined") return false;
  const canvasPrototype = window.HTMLCanvasElement?.prototype;
  const contextPrototype = window.CanvasRenderingContext2D?.prototype as (CanvasRenderingContext2D & {
    drawElementImage?: unknown;
  }) | undefined;
  return Boolean(
    "gpu" in navigator
    && canvasPrototype
    && "layoutSubtree" in canvasPrototype
    && typeof contextPrototype?.drawElementImage === "function"
  );
}

function useLiquidGlassSupport() {
  const [supported, setSupported] = useState(detectLiquidGlassSupport);
  useEffect(() => {
    setSupported(detectLiquidGlassSupport());
  }, []);
  return supported;
}

function useLiquidGlassSize<T extends HTMLElement>() {
  const ref = useRef<T | null>(null);
  const [size, setSize] = useState({ width: 0, height: 0 });
  useLayoutEffect(() => {
    const element = ref.current;
    if (!element) return undefined;
    const update = () => {
      const rect = element.getBoundingClientRect();
      const width = Math.round(rect.width);
      const height = Math.round(rect.height);
      setSize((current) => current.width === width && current.height === height ? current : { width, height });
    };
    update();
    const observer = new ResizeObserver(update);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  return { ref, size };
}

const LiquidGlassLayer = memo(function LiquidGlassLayer({
  tone = "panel",
  cornerRadius = 16,
  shape = "rounded",
  blur,
  tint,
  opacity: opacityOverride,
  active,
  hover,
  disabled,
  className
}: {
  tone?: LiquidGlassTone;
  cornerRadius?: number;
  shape?: "rounded" | "pill";
  blur?: number;
  tint?: LiquidGlassColor;
  opacity?: number;
  active?: boolean;
  hover?: boolean;
  disabled?: boolean;
  className?: string;
}) {
  const runtime = useContext(LiquidGlassRuntimeContext);
  const { ref, size } = useLiquidGlassSize<HTMLDivElement>();
  const [failed, setFailed] = useState(false);
  const config = liquidGlassToneConfig[tone];
  const canRender = runtime.enabled && runtime.supported && !failed && size.width > 4 && size.height > 4;
  const resolvedCornerRadius = shape === "pill" ? Math.max(size.width, size.height) : cornerRadius;
  const opacityBase = opacityOverride ?? config.opacity;
  const opacity = Math.max(0.18, Math.min(0.94, opacityBase + (active ? 0.08 : 0) + (hover ? 0.04 : 0) - (disabled ? 0.26 : 0)));

  return (
    <div ref={ref} className={cx("liquid-glass-layer", `liquid-glass-layer-${tone}`, className)} aria-hidden="true">
      {canRender && (
        <LiquidCanvasRoot
          className="liquid-glass-canvas-root"
          canvasClassName="liquid-glass-canvas"
          maxDpr={1.35}
          frameloop="demand"
          proposal={size}
          onError={() => setFailed(true)}
        >
          <LiquidFrame width={size.width} height={size.height}>
            <LiquidGlassContainer
              blur={blur ?? config.blur}
              opacity={opacity}
              thickness={config.thickness}
              tint={tint ?? config.tint}
              shadowColor={config.shadowColor}
              shadowBlur={config.shadowBlur}
              shadowOffsetY={config.shadowOffsetY}
              specularOpacity={config.specularOpacity}
              displacementFactor={0.85}
              displacementBlur={5}
              reflectionOffset={14}
              spacing={10}
            >
              <LiquidGlass cornerRadius={resolvedCornerRadius} cornerSmoothing={0.62}>
                <LiquidHtml sizing="fill">
                  <span className="liquid-glass-html-fill" />
                </LiquidHtml>
              </LiquidGlass>
            </LiquidGlassContainer>
          </LiquidFrame>
        </LiquidCanvasRoot>
      )}
    </div>
  );
});

function LiquidGlassSurface({
  children,
  className,
  tone = "panel",
  cornerRadius = 16,
  shape = "rounded",
  blur,
  tint,
  opacity,
  active,
  hover,
  disabled
}: {
  children: ReactNode;
  className?: string;
  tone?: LiquidGlassTone;
  cornerRadius?: number;
  shape?: "rounded" | "pill";
  blur?: number;
  tint?: LiquidGlassColor;
  opacity?: number;
  active?: boolean;
  hover?: boolean;
  disabled?: boolean;
}) {
  return (
    <div className={cx("liquid-glass-surface", className, active && "liquid-glass-active", hover && "liquid-glass-hover", disabled && "liquid-glass-disabled")}>
      <LiquidGlassLayer
        tone={tone}
        cornerRadius={cornerRadius}
        shape={shape}
        blur={blur}
        tint={tint}
        opacity={opacity}
        active={active}
        hover={hover}
        disabled={disabled}
      />
      {children}
    </div>
  );
}

function useOutsideDismiss(active: boolean, containerRef: RefObject<HTMLElement | null>, onDismiss: () => void) {
  const dismissRef = useRef(onDismiss);

  useEffect(() => {
    dismissRef.current = onDismiss;
  }, [onDismiss]);

  useEffect(() => {
    if (!active) return undefined;

    const handlePointerDown = (event: PointerEvent) => {
      const target = event.target;
      if (!(target instanceof Node)) return;
      if (containerRef.current?.contains(target)) return;
      dismissRef.current();
    };

    const handleKeyDown = (event: globalThis.KeyboardEvent) => {
      if (event.key === "Escape") dismissRef.current();
    };

    document.addEventListener("pointerdown", handlePointerDown, true);
    document.addEventListener("keydown", handleKeyDown, true);
    return () => {
      document.removeEventListener("pointerdown", handlePointerDown, true);
      document.removeEventListener("keydown", handleKeyDown, true);
    };
  }, [active, containerRef]);
}

function cssKey(value?: string) {
  return (value || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

const initialAppearanceSettingKeys = [
  "themeMode",
  "colorTheme",
  "appChromeStyle",
  "lightThemeAccent",
  "lightThemeBackground",
  "lightThemeForeground",
  "lightThemeUIFont",
  "lightThemeCodeFont",
  "lightThemeTranslucentSidebar",
  "lightThemeContrast",
  "lightThemeCodeThemeID",
  "lightThemeDiffAdded",
  "lightThemeDiffRemoved",
  "lightThemeSkill",
  "darkThemeAccent",
  "darkThemeBackground",
  "darkThemeForeground",
  "darkThemeUIFont",
  "darkThemeCodeFont",
  "darkThemeTranslucentSidebar",
  "darkThemeContrast",
  "darkThemeCodeThemeID",
  "darkThemeDiffAdded",
  "darkThemeDiffRemoved",
  "darkThemeSkill",
  "pointerCursors",
  "fontSmoothing",
  "reduceMotionMode",
  "uiFontSize",
  "codeFontSize"
] as const satisfies ReadonlyArray<keyof SettingsSnapshot>;

function readInitialAppearanceSettings(): Partial<SettingsSnapshot> {
  if (typeof window === "undefined") return {};
  const raw = new URLSearchParams(window.location.search).get("initialAppearance");
  if (!raw) return {};
  try {
    const parsed = JSON.parse(raw) as Record<string, unknown>;
    const next: Partial<SettingsSnapshot> = {};
    for (const key of initialAppearanceSettingKeys) {
      const value = parsed[key];
      if (value === undefined) continue;
      if (
        key === "lightThemeTranslucentSidebar" ||
        key === "darkThemeTranslucentSidebar" ||
        key === "pointerCursors" ||
        key === "fontSmoothing"
      ) {
        next[key] = Boolean(value) as never;
      } else {
        next[key] = String(value) as never;
      }
    }
    return next;
  } catch {
    return {};
  }
}

/**
 * Single source of truth for appearance settings across every Electron window.
 *
 * Each window mounts a React tree with its own `App()` instance — they're separate
 * processes, separate JS heaps. To keep theme/font/contrast in sync, we:
 *
 *  1. Seed each window with `initialAppearance` from the URL query at boot.
 *  2. Subscribe to `openassist:settings-updated` broadcast (sent by main after
 *     every successful `updateSetting` IPC call).
 *  3. Merge incoming snapshots into the in-memory copy and re-render every
 *     consumer via context — so theme changes propagate even though the
 *     window's own `appState.settings` (if any) is decoupled.
 *
 * Window shells call `useAppearanceSettings()` instead of reading their own
 * local copies.
 */
type AppearancePatch = Partial<SettingsSnapshot>;

const AppearanceSettingsContext = createContext<AppearancePatch>({});

function useAppearanceSettings(): AppearancePatch {
  return useContext(AppearanceSettingsContext);
}

function AppearanceSettingsProvider({
  overrides,
  children
}: {
  overrides?: AppearancePatch;
  children: React.ReactNode;
}) {
  const [settings, setSettings] = useState<AppearancePatch>(() => readInitialAppearanceSettings());

  useEffect(() => {
    const unsubscribe = window.openAssistElectron?.onSettingsUpdated?.((next) => {
      if (!next || typeof next !== "object") return;
      setSettings((current) => ({ ...current, ...(next as AppearancePatch) }));
    });
    return () => unsubscribe?.();
  }, []);

  // Merge any caller-supplied overrides (e.g. the main shell already owns
  // `appState.settings` and feeds it in so context + local state agree).
  const value = useMemo<AppearancePatch>(
    () => ({ ...settings, ...(overrides ?? {}) }),
    [settings, overrides]
  );

  // Body-level toggles that should apply window-wide (covers portals).
  useEffect(() => {
    if (typeof document === "undefined") return;
    const smoothingOff = (value.fontSmoothing ?? true) === false;
    document.body.classList.toggle("font-smoothing-off", smoothingOff);
  }, [value.fontSmoothing]);

  return (
    <AppearanceSettingsContext.Provider value={value}>
      {children}
    </AppearanceSettingsContext.Provider>
  );
}

function appShellStyleForSettings(
  settings: Partial<SettingsSnapshot>,
  systemThemeMode: "dark" | "light",
  options: { compact?: boolean; sidebarHidden?: boolean; sidebarWidth?: number } = {}
) {
  const resolvedMode = resolveThemeMode(settings.themeMode, systemThemeMode);
  const prefix = resolvedMode === "light" ? "lightTheme" : "darkTheme";
  const accent = String(settings[`${prefix}Accent` as keyof SettingsSnapshot] || (resolvedMode === "light" ? "#0169CC" : "#F9861A"));
  const background = String(settings[`${prefix}Background` as keyof SettingsSnapshot] || (resolvedMode === "light" ? "#FFFFFF" : "#0D1117"));
  const foreground = String(settings[`${prefix}Foreground` as keyof SettingsSnapshot] || (resolvedMode === "light" ? "#0D0D0D" : "#E6EDF3"));
  const uiFont = normalizeUIFontValue(settings[`${prefix}UIFont` as keyof SettingsSnapshot]);
  const codeFont = String(settings[`${prefix}CodeFont` as keyof SettingsSnapshot] || "ui-monospace, SFMono-Regular, Menlo, monospace");
  const contrast = String(settings[`${prefix}Contrast` as keyof SettingsSnapshot] || "70");
  const contrastNumber = Math.min(100, Math.max(0, Number(contrast) || 70));
  const diffAdded = String(settings[`${prefix}DiffAdded` as keyof SettingsSnapshot] || (resolvedMode === "light" ? "#00a240" : "#40c977"));
  const diffRemoved = String(settings[`${prefix}DiffRemoved` as keyof SettingsSnapshot] || (resolvedMode === "light" ? "#ba2623" : "#fa423e"));
  const skill = String(settings[`${prefix}Skill` as keyof SettingsSnapshot] || (resolvedMode === "light" ? "#924ff7" : "#ad7bf9"));
  const codeThemeID = String(settings[`${prefix}CodeThemeID` as keyof SettingsSnapshot] || codexThemeDefaults[resolvedMode].codeThemeId);
  const codePalette = codexSeedFor(codeThemeID, resolvedMode);
  const translucentSidebar = Boolean(settings[`${prefix}TranslucentSidebar` as keyof SettingsSnapshot]);
  const percent = (value: number) => `${Math.round(value)}%`;
  const style = {
    "--theme-accent": accent,
    "--theme-background": background,
    "--theme-foreground": foreground,
    "--theme-ui-font": uiFont,
    "--theme-code-font": codeFont,
    "--theme-contrast": contrast,
    "--theme-diff-added": diffAdded,
    "--theme-diff-removed": diffRemoved,
    "--theme-skill": skill,
    "--theme-surface-mix": percent(2 + contrastNumber * 0.09),
    "--theme-surface-strong-mix": percent(4 + contrastNumber * 0.11),
    "--theme-surface-hover-mix": percent(7 + contrastNumber * 0.11),
    "--theme-line-mix": percent(5 + contrastNumber * 0.11),
    "--theme-line-strong-mix": percent(8 + contrastNumber * 0.13),
    "--theme-chrome-mix": translucentSidebar ? (resolvedMode === "light" ? "64%" : "48%") : (resolvedMode === "light" ? "94%" : "92%"),
    "--theme-sidebar-base-mix": translucentSidebar
      ? (resolvedMode === "light" ? "38%" : "30%")
      : (resolvedMode === "light" ? "94%" : "92%"),
    "--theme-sidebar-highlight-mix": translucentSidebar
      ? (resolvedMode === "light" ? "9%" : "8%")
      : (resolvedMode === "light" ? "5%" : "3%"),
    "--theme-sidebar-shadow-alpha": translucentSidebar
      ? (resolvedMode === "light" ? "0" : "0.05")
      : (resolvedMode === "light" ? "0" : "0.18"),
    "--theme-sidebar-shadow-strong-alpha": translucentSidebar
      ? (resolvedMode === "light" ? "0" : "0.11")
      : (resolvedMode === "light" ? "0" : "0.32"),
    "--theme-sidebar-blur": translucentSidebar ? "56px" : "18px",
    "--note-code-keyword": codePalette.keyword,
    "--note-code-builtin": codePalette.builtin,
    "--note-code-function": codePalette.function,
    "--note-code-class": codePalette.builtin,
    "--note-code-number": codePalette.number,
    "--note-code-string": codePalette.string,
    "--note-code-comment": codePalette.comment,
    "--note-code-property": codePalette.builtin,
    "--note-code-tag": codePalette.keyword,
    "--note-code-attr-name": codePalette.function,
    "--note-code-attr-value": codePalette.string,
    "--note-code-selector": codePalette.builtin,
    "--note-code-variable": codePalette.keyword,
    "--note-code-inserted": diffAdded,
    "--note-code-deleted": diffRemoved,
    "--ui-font-size": `${Number(normalizeUIFontSize(settings.uiFontSize)) || 14}px`,
    "--code-font-size": `${Number(settings.codeFontSize) || 12}px`
  } as CSSProperties & Record<string, string>;
  if (!options.compact) {
    style["--sidebar-width"] = `${options.sidebarHidden ? 0 : options.sidebarWidth ?? 0}px`;
  }
  return style;
}

function providerKey(raw?: string): ProviderKey {
  const value = (raw || "").toLowerCase();
  if (value.includes("copilot") || value.includes("github")) return "copilot";
  if (value.includes("claude")) return "claudeCode";
  if (value.includes("antigravity") || value === "agy") return "antigravityCLI";
  if (value.includes("ollama")) return "ollamaLocal";
  return "codex";
}

function isRuntimeProviderKey(key: ProviderKey): key is RuntimeProviderKey {
  return key === "codex" || key === "copilot" || key === "claudeCode" || key === "antigravityCLI" || key === "ollamaLocal";
}

function runtimeProviderKey(raw?: string): RuntimeProviderKey {
  const key = providerKey(raw);
  return isRuntimeProviderKey(key) ? key : "codex";
}

function availableRuntimeProviderOptions(settings?: SettingsSnapshot): RuntimeProviderOption[] {
  const current = runtimeProviderKey(settings?.assistantBackend || "codex");
  const allowed = new Set<RuntimeProviderKey>();
  for (const rawBackend of settings?.availableAssistantBackends ?? []) {
    const key = providerKey(rawBackend);
    if (isRuntimeProviderKey(key)) allowed.add(key);
  }
  if (!allowed.size) {
    for (const option of runtimeProviderOptions) allowed.add(option.key);
  }
  allowed.add(current);
  return runtimeProviderOptions.map((option) => ({
    ...option,
    detail: allowed.has(option.key) ? option.detail : setupRequiredDetails[option.key]
  }));
}

function speechRecognitionConstructor(): SpeechRecognitionConstructor | undefined {
  const speechWindow = window as Window & {
    SpeechRecognition?: SpeechRecognitionConstructor;
    webkitSpeechRecognition?: SpeechRecognitionConstructor;
  };
  return speechWindow.SpeechRecognition ?? speechWindow.webkitSpeechRecognition;
}

function appendVoiceDraft(baseText: string, voiceText: string) {
  const base = baseText.trimEnd();
  const voice = voiceText.trim();
  if (!base) return voice;
  if (!voice) return base;
  return `${base}${base.endsWith("\n") ? "" : " "}${voice}`;
}

function isEditableTextInput(element: Element | null): element is HTMLInputElement | HTMLTextAreaElement {
  if (element instanceof HTMLTextAreaElement) return !element.disabled && !element.readOnly;
  if (!(element instanceof HTMLInputElement) || element.disabled || element.readOnly) return false;
  const editableTypes = new Set(["", "text", "search", "url", "tel", "email", "password"]);
  return editableTypes.has(element.type);
}

function insertTextIntoFocusedAppField(text: string) {
  const activeElement = document.activeElement;
  if (isEditableTextInput(activeElement)) {
    const start = activeElement.selectionStart ?? activeElement.value.length;
    const end = activeElement.selectionEnd ?? activeElement.value.length;
    const before = activeElement.value.slice(0, start);
    const after = activeElement.value.slice(end);
    const normalizedText = text.trim();
    const leadingSpace = before && !/\s$/.test(before) ? " " : "";
    const trailingSpace = after && !/^\s/.test(after) ? " " : "";
    const insertedText = `${leadingSpace}${normalizedText}${trailingSpace}`;
    const nextValue = `${before}${insertedText}${after}`;
    const valueSetter = Object.getOwnPropertyDescriptor(
      activeElement instanceof HTMLTextAreaElement ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype,
      "value"
    )?.set;
    valueSetter?.call(activeElement, nextValue);
    if (!valueSetter) activeElement.value = nextValue;
    const nextCursor = before.length + insertedText.length;
    try {
      activeElement.setSelectionRange(nextCursor, nextCursor);
    } catch {
      // Some input types do not support selection ranges.
    }
    activeElement.dispatchEvent(new Event("input", { bubbles: true }));
    return true;
  }

  if (activeElement instanceof HTMLElement && activeElement.isContentEditable) {
    const selection = window.getSelection();
    if (!selection || selection.rangeCount === 0 || !activeElement.contains(selection.anchorNode)) return false;
    const range = selection.getRangeAt(0);
    range.deleteContents();
    const textNode = document.createTextNode(text.trim());
    range.insertNode(textNode);
    range.setStartAfter(textNode);
    range.setEndAfter(textNode);
    selection.removeAllRanges();
    selection.addRange(range);
    activeElement.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertText", data: text.trim() }));
    return true;
  }

  return false;
}

function withTimeout<T>(promise: Promise<T> | undefined, timeoutMs: number, message: string) {
  if (!promise) return Promise.resolve(undefined);
  return new Promise<T>((resolve, reject) => {
    const timeout = window.setTimeout(() => reject(new Error(message)), timeoutMs);
    promise
      .then(resolve, reject)
      .finally(() => window.clearTimeout(timeout));
  });
}

function ProviderMark({ provider, className }: { provider?: string; className?: string }) {
  const key = providerKey(provider);
  const mark = providerMarks[key];
  const shouldRenderOriginalColors = originalColorProviderMarks.has(key);
  return (
    <span className={cx("provider-mark", `provider-mark-${key}`, className)} aria-hidden="true">
      {mark && shouldRenderOriginalColors ? (
        <img className="provider-mark-glyph provider-mark-image provider-mark-img" src={mark} alt="" draggable={false} />
      ) : mark ? (
        <span
          className="provider-mark-glyph provider-mark-image"
          style={{
            WebkitMaskImage: `url("${mark}")`,
            maskImage: `url("${mark}")`
          } as CSSProperties}
        />
      ) : (
        <Bot size={14} />
      )}
    </span>
  );
}

