  const downloadOllamaModel = async () => {
    if (ollamaRuntimeStatus?.updateAvailable) {
      setProviderActionMessage(
        ollamaRuntimeStatus.installMessage
        || `Update Ollama ${ollamaRuntimeStatus.latestVersion || ""} before downloading newer models.`.trim()
      );
      return;
    }
    const modelID = (ollamaDownloadSelection === OLLAMA_CUSTOM_MODEL_VALUE
      ? ollamaModelDraft
      : ollamaDownloadSelection).trim();
    if (!modelID) {
      setProviderActionMessage("Choose a model from the catalog or enter a custom Ollama model name first.");
      return;
    }
    setOllamaModelActionID(`download:${modelID}`);
    setOllamaDownloadProgress({ modelID, status: "Starting download", percent: 0 });
    setProviderActionMessage(`Downloading ${modelID}. This can take a while.`);
    try {
      const result = await window.openAssistElectron?.pullOllamaModel?.(modelID);
      setOllamaModels(result?.models ?? []);
      setOllamaModelsLoaded(true);
      await onUpdateSetting("promptRewriteModel", modelID);
      setOllamaDownloadSelection(modelID);
      setOllamaModelDraft(modelID);
      setOllamaDownloadProgress({ modelID, status: "Downloaded", percent: 100, done: true });
      setProviderActionMessage(`Downloaded and selected ${modelID}.`);
      await refreshOllamaCatalog(modelID);
      onRefresh();
    } catch (error) {
      setProviderActionMessage(error instanceof Error ? error.message : `Could not download ${modelID}.`);
    } finally {
      setOllamaModelActionID(undefined);
    }
  };

  const deleteOllamaModel = async (modelID: string) => {
    const targetModelID = modelID.trim();
    if (!targetModelID) return;
    const confirmed = window.confirm(`Delete the local Ollama model "${targetModelID}" from this Mac?`);
    if (!confirmed) return;
    setOllamaModelActionID(`delete:${targetModelID}`);
    setProviderActionMessage(`Deleting ${targetModelID}...`);
    try {
      const result = await window.openAssistElectron?.deleteOllamaModel?.(targetModelID);
      const nextModels = result?.models ?? [];
      setOllamaModels(nextModels);
      setOllamaModelsLoaded(true);
      const selectedModelID = settings?.promptRewriteModel?.trim();
      if (selectedModelID && selectedModelID.toLowerCase() === targetModelID.toLowerCase()) {
        const replacementModelID = nextModels.find((model) => model.id.trim())?.id;
        if (replacementModelID) {
          await onUpdateSetting("promptRewriteModel", replacementModelID);
          setOllamaModelDraft(replacementModelID);
          setProviderActionMessage(`Deleted ${targetModelID}. Switched to ${replacementModelID}.`);
        } else {
          setProviderActionMessage(`Deleted ${targetModelID}. Download another model before using Ollama.`);
        }
      } else {
        setProviderActionMessage(`Deleted ${targetModelID}.`);
      }
      await refreshOllamaCatalog(settings?.promptRewriteModel);
      onRefresh();
    } catch (error) {
      setProviderActionMessage(error instanceof Error ? error.message : `Could not delete ${targetModelID}.`);
    } finally {
      setOllamaModelActionID(undefined);
    }
  };

