  const visibleThreadTitle = selectedThreadRun?.title || threadDetail?.title || selectedThread?.title || "Ok";
  const visibleThreadDetail = useMemo<ThreadDetail | null>(() => {
    if (!threadDetail && !selectedThreadRun) return null;
    return {
      ...(threadDetail ?? {
        threadID: selectedThreadRun?.threadID ?? selectedThreadID ?? "new",
        title: visibleThreadTitle,
        messages: []
      }),
      title: visibleThreadTitle,
      messages: visibleThreadMessages
    };
  }, [selectedThreadID, selectedThreadRun, threadDetail, visibleThreadMessages, visibleThreadTitle]);

  const loadOlderThreadMessages = useCallback(async () => {
    const current = threadDetail;
    const threadID = current?.threadID ?? selectedThreadIDRef.current ?? selectedThreadID;
    const beforeMessageID = current?.oldestMessageID ?? current?.messages[0]?.id;
    if (!threadID || !beforeMessageID || !current?.hasMoreBefore) return;
    if (olderThreadMessagesLoadingRef.current) return;

    olderThreadMessagesLoadingRef.current = true;
    setOlderThreadMessagesLoading(true);
    try {
      const page = await window.openAssistElectron?.loadOlderThreadMessages?.(
        threadID,
        beforeMessageID,
        THREAD_TURN_PAGE_SIZE
      );
      if (!page) return;
      const activeThreadID = selectedThreadIDRef.current ?? selectedThreadID;
      if (activeThreadID && !sameID(activeThreadID, threadID)) return;
      setThreadDetail((existing) => {
        if (!existing || !sameID(existing.threadID, threadID)) return existing;
        const existingIDs = new Set(existing.messages.map((message) => message.id));
        const olderMessages = page.messages.filter((message) => !existingIDs.has(message.id));
        return {
          ...existing,
          messages: [...olderMessages, ...existing.messages],
          hasMoreBefore: page.hasMoreBefore,
          oldestMessageID: page.oldestMessageID ?? olderMessages[0]?.id ?? existing.oldestMessageID,
          loadedTurnCount: (existing.loadedTurnCount ?? 0) + (page.loadedTurnCount ?? 0)
        };
      });
    } catch (error) {
      console.error(error);
      setProviderStatus("Could not load older messages.");
      window.setTimeout(() => setProviderStatus((currentStatus) =>
        currentStatus === "Could not load older messages." ? null : currentStatus
      ), 2200);
    } finally {
      olderThreadMessagesLoadingRef.current = false;
      setOlderThreadMessagesLoading(false);
    }
  }, [selectedThreadID, threadDetail]);

