  const syncWakeWordAfterSettingsChange = async (settingsSnapshot: SettingsSnapshot, changedKey: SettingsUpdateKey) => {
    if (!["todayWakeWordEnabled", "todayWakeWordPhrase", "autoDetectMicrophone", "selectedMicrophoneUID"].includes(changedKey)) return;
    const electron = window.openAssistElectron;
    if (!electron?.stopWakeWordForToday) return;
    const enabled = settingsSnapshot.todayWakeWordEnabled ?? false;
    const result = await electron.stopWakeWordForToday(enabled ? "paused" : "manual");
    if (result?.status) {
      setTodayWakeWordStatus({
        ...result.status,
        phrase: settingsSnapshot.todayWakeWordPhrase || result.status.phrase,
        message: enabled
          ? "Wake word is paused so the microphone stays off. Use Realtime or the Live Voice shortcut to listen."
          : result.status.message
      });
    }
  };

	  const updateSettingValue = async (key: SettingsUpdateKey, value: SettingsUpdateValue) => {
    const previousSettings = appState.settings;
    let confirmedSettingsForWake: SettingsSnapshot | null = null;
    setAppState((current) => ({ ...current, settings: { ...current.settings, [key]: value } as SettingsSnapshot }));
    try {
	      const nextSettings = await window.openAssistElectron?.updateSetting(key, value);
		      if (nextSettings) {
        const normalizedSettings = normalizeRendererSettings(nextSettings);
        const confirmedValue = normalizedSettings[key as keyof SettingsSnapshot] ?? value;
        confirmedSettingsForWake = {
          ...appState.settings,
          ...normalizedSettings,
          [key]: confirmedValue
        } as SettingsSnapshot;
        setSettingsHydrated(true);
		        setAppState((current) => ({
	          ...current,
	          settings: {
              ...current.settings,
	            ...normalizedSettings,
              [key]: confirmedValue,
	            availableMicrophones: current.settings.availableMicrophones
	          } as SettingsSnapshot
	        }));
        if (key === "compactEdge" && compact && compactSurfaceMode(normalizedSettings.compactStyle) === "sidebar") {
          void window.openAssistElectron?.setWindowMode("sidebar", sidebarOpen, nextSettings.compactEdge === "left" ? "left" : "right");
        }
        if (key === "compactStyle" && compact) {
          const nextCompactMode = compactSurfaceMode(confirmedValue);
          const nextEdge = normalizedSettings.compactEdge === "left" ? "left" : "right";
          const revealNextNotch = nextCompactMode === "notch" && (sidebarOpen || notchDockRevealed);
          if (!isSettingsWindow) setNotchDockRevealed(revealNextNotch);
          void window.openAssistElectron?.setWindowMode(nextCompactMode, sidebarOpen, nextEdge, revealNextNotch);
        }
      }
    } catch (error) {
      setAppState((current) => ({ ...current, settings: previousSettings }));
      console.error(error);
    }
    if (confirmedSettingsForWake) {
      void syncWakeWordAfterSettingsChange(confirmedSettingsForWake, key).catch((error) => {
        setTodayWakeWordStatus({
          state: "error",
          source: "today",
          engine: "appleSpeechPhrase",
          phrase: confirmedSettingsForWake?.todayWakeWordPhrase || "Hey Open Assist",
          enabled: confirmedSettingsForWake?.todayWakeWordEnabled ?? false,
          error: error instanceof Error ? error.message : "Could not update wake word."
        });
      });
    }
    if (key === "compactEdge" && compact && compactSurface === "sidebar") {
      void window.openAssistElectron?.setWindowMode("sidebar", sidebarOpen, String(value) === "left" ? "left" : "right");
    }
    if (key === "compactStyle") {
      const nextCompactMode = compactSurfaceMode(value);
      if (compact) {
        const nextEdge = appState.settings.compactEdge === "left" ? "left" : "right";
        const revealNextNotch = nextCompactMode === "notch" && (sidebarOpen || notchDockRevealed);
        if (!isSettingsWindow) setNotchDockRevealed(revealNextNotch);
        void window.openAssistElectron?.setWindowMode(nextCompactMode, sidebarOpen, nextEdge, revealNextNotch);
      } else {
        const nextEdge = appState.settings.compactEdge === "left" ? "left" : "right";
        if (!isSettingsWindow) {
          setCompact(true);
          setSidebarOpen(true);
          setNotchDockRevealed(nextCompactMode === "notch");
        }
        void window.openAssistElectron?.setWindowMode(nextCompactMode, true, nextEdge, nextCompactMode === "notch");
      }
    }
  };

	  const updateSettingsValues = async (updates: SettingsUpdatePatch[]) => {
    if (updates.length === 0) return;
    const previousSettings = appState.settings;
    const optimisticSettings = updates.reduce<Record<string, SettingsUpdateValue>>(
      (settings, update) => ({ ...settings, [update.key]: update.value }),
      {}
    );
    setAppState((current) => ({
      ...current,
      settings: {
        ...current.settings,
        ...optimisticSettings
      } as SettingsSnapshot
    }));
    try {
      let nextSettings: SettingsSnapshot | undefined;
      if (window.openAssistElectron?.updateSettings) {
        nextSettings = await window.openAssistElectron.updateSettings(updates);
      } else {
        for (const update of updates) {
          nextSettings = await window.openAssistElectron?.updateSetting(update.key, update.value);
        }
      }
      if (nextSettings) {
        const normalizedSettings = normalizeRendererSettings(nextSettings);
        setSettingsHydrated(true);
        setAppState((current) => ({
          ...current,
          settings: {
            ...current.settings,
            ...normalizedSettings,
            availableMicrophones: current.settings.availableMicrophones
          } as SettingsSnapshot
        }));
      }
    } catch (error) {
      setAppState((current) => ({ ...current, settings: previousSettings }));
      console.error(error);
      throw error;
    }
  };

	  const updateShortcutValue = async (target: ShortcutTarget, keyCode: number, modifiers: number) => {
	    const nextSettings = await window.openAssistElectron?.updateShortcut(target, keyCode, modifiers);
		    if (nextSettings) {
        const normalizedSettings = normalizeRendererSettings(nextSettings);
        setSettingsHydrated(true);
		      setAppState((current) => ({
	        ...current,
	        settings: {
	          ...normalizedSettings,
	          availableMicrophones: current.settings.availableMicrophones
	        }
	      }));
	    }
	    return nextSettings;
	  };

		  const applySettingsSnapshot = (settings?: SettingsSnapshot) => {
		    if (!settings) return;
      const normalizedSettings = normalizeRendererSettings(settings);
      setSettingsHydrated(true);
		    setAppState((current) => ({
	      ...current,
	      settings: {
	        ...normalizedSettings,
	        availableMicrophones: current.settings.availableMicrophones
	      }
	    }));
	  };

